print(f"Position de flag{{: {idx}")

# Regardons les bytes autour de flag{
print("Bytes autour de flag{:")
for i in range(idx, min(idx+50, len(data))):
    print(f"  {i}: 0x{data[i]:02x} = {chr(data[i]) if 32 <= data[i] <= 126 else '?'}")

